'use strict';
const http=require('node:http'),fs=require('node:fs'),path=require('node:path'),{chromium}=require('playwright');
const root=process.cwd(),mime={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.json':'application/json; charset=utf-8'};
const server=http.createServer((req,res)=>{const p=decodeURIComponent(new URL(req.url,'http://127.0.0.1').pathname),f=path.resolve(root,'.'+p);if(!f.startsWith(root+path.sep)||!fs.existsSync(f)||!fs.statSync(f).isFile()){res.writeHead(404);res.end('Not found');return;}res.writeHead(200,{'content-type':mime[path.extname(f)]||'application/octet-stream'});fs.createReadStream(f).pipe(res);});
(async()=>{let browser;try{await new Promise((ok,no)=>{server.once('error',no);server.listen(4174,'127.0.0.1',ok);});browser=await chromium.launch({headless:true});const context=await browser.newContext(),page=await context.newPage();page.on('pageerror',e=>{throw e;});await page.goto('http://127.0.0.1:4174/experiments/change-journal-prototype/storage-write-path-test.html',{waitUntil:'load'});await page.waitForFunction(()=>window.__storageWritePathResult!==undefined,{timeout:15000});const r=await page.evaluate(()=>window.__storageWritePathResult);r.lines.forEach(x=>console.log(x));console.log('STORAGE WRITE-PATH RESULT: '+r.passed+'/'+r.total);if(r.passed!==r.total||r.total!==10)throw new Error('Storage write-path test failed');await context.close();}finally{if(browser)await browser.close();await new Promise(ok=>server.close(ok));}})().catch(e=>{console.error(e);process.exitCode=1;});